class Solution {vector<int> p,sz;int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a==b)return;if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}
public:vector<int> minimumCost(int n,vector<vector<int>>& edges,vector<vector<int>>& query){
 p.resize(n);iota(p.begin(),p.end(),0);sz.assign(n,1);for(auto &e:edges)join(e[0],e[1]);
 vector<int> cost(n,-1);for(auto &e:edges)cost[find(e[0])]&=e[2];
 vector<int> ans;for(auto &q:query){if(q[0]==q[1])ans.push_back(0);else if(find(q[0])!=find(q[1]))ans.push_back(-1);else ans.push_back(cost[find(q[0])]);}return ans;
}};
